WITH matched AS (SELECT s.*, pr.id AS promo_id, pr.promo_code, pr.discount_pct FROM orders s INNER JOIN promotions pr ON COALESCE(s.channel, 'store') = pr.channel AND s.order_date >= pr.starts_on AND s.order_date < pr.ends_on + INTERVAL 14 DAYS) SELECT id, customer_id, store_id, order_date, status, amount, discount, shipping_fee, promo_id FROM matched ORDER BY store_id DESC NULLS LAST, amount;
